import { useId, type HTMLAttributes, type ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// A bordered box for one subject (console2.css .v2-card): a head with its title and actions over a hairline, then the
// body. Square, no shadow. `framed` adds the website's double rule, a second hairline 4px outside, for the one block a
// page leads with. `flush` drops the body's padding, for a table that runs to the edges.
export interface CardProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title?: string
  framed?: boolean
  flush?: boolean
  /** The head's actions (Vue's `actions` slot): links or buttons at its end. */
  actions?: ReactNode
}

export function Card({ title, framed, flush, actions, className, children, ...rest }: CardProps) {
  const titleId = `card-${useId()}`
  return (
    <section data-ds="card" className={cn('border border-edge bg-surface', framed && 'outline outline-offset-4 outline-edge', className)} aria-labelledby={title ? titleId : undefined} {...rest}>
      {(title || actions) && (
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 border-b border-edge px-4 py-3">
          {title && <h3 id={titleId} className="type-ui-strong">{title}</h3>}
          {actions && <div className="flex items-center gap-2 type-meta text-fg-muted">{actions}</div>}
        </div>
      )}
      <div className={flush ? undefined : 'p-4'}>{children}</div>
    </section>
  )
}

export default Card

import type { ComponentType, ReactNode } from 'react'
import { ArrowRight } from 'lucide-react'
import { cn } from '@/react/lib/cn'

// A whole card that opens something (console2.css .v2-door): a way in, such as Connect an app or Send by API. Its
// border turns ink under the pointer and while what it opens is open (`expanded`). One link or one button, never a
// clickable div.
export interface DoorProps {
  title: string
  description?: string
  /** A Lucide icon component, drawn at 14px. */
  icon?: ComponentType<{ size?: number, strokeWidth?: number, 'aria-hidden'?: boolean | 'true' }>
  href?: string
  arrow?: boolean
  expanded?: boolean
  className?: string
  onClick?: () => void
  /** Replaces the description (Vue's default slot). */
  children?: ReactNode
}

export function Door({ title, description, icon: Icon, href, arrow, expanded, className, onClick, children }: DoorProps) {
  const classes = cn('flex cursor-pointer flex-col gap-1 border border-edge bg-surface p-3 text-left transition-[border-color,background-color] duration-120 ease-standard hover:border-edge-focus active:bg-surface-subtle aria-expanded:border-edge-focus', className)
  const content = (
    <>
      <span className="flex items-center gap-2 type-ui-strong">
        {Icon && <Icon size={14} strokeWidth={1.5} aria-hidden="true" />}{title}
        {arrow && <ArrowRight size={12} strokeWidth={1.5} className="ml-auto text-fg-muted" aria-hidden="true" />}
      </span>
      {(description || children) && <span className="type-meta text-fg-muted">{children ?? description}</span>}
    </>
  )
  return href
    ? <a data-ds="door" href={href} className={classes} onClick={onClick}>{content}</a>
    : <button data-ds="door" type="button" aria-expanded={expanded} className={classes} onClick={onClick}>{content}</button>
}

export default Door

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define, uid } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Card.vue as <conare-card>: a bordered box for one subject (console2.css .v2-card): a head with its title and actions
// over a hairline, then the body. Square, no shadow. `framed` adds the website's double rule, a second hairline 4px
// outside, for the one block a page leads with. `flush` drops the body's padding.

/**
 * @summary A bordered box for one subject.
 * @slot - The body.
 * @slot actions - The head's actions: links or buttons at its end.
 */
export class Card extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { heading: {}, framed: { type: Boolean }, flush: { type: Boolean } }

	/** The head's title (Vue's `title`; `title` is HTML's tooltip attribute). */
	heading = ''
	/** The website's double rule. */
	framed = false
	/** No padding in the body, for a table that runs to the edges. */
	flush = false
	private headingId = uid('card')

	render() {
		const actions = this.hasSlot('actions')
		return html`<section data-ds="card" class=${['border border-edge bg-surface', this.framed ? 'outline outline-offset-4 outline-edge' : ''].join(' ')} aria-labelledby=${ifDefined(this.heading ? this.headingId : undefined)}>
			${this.heading || actions
				? html`<div class="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 border-b border-edge px-4 py-3">${this.heading ? html`<h3 id=${this.headingId} class="type-ui-strong">${this.heading}</h3>` : nothing}${actions ? html`<div class="flex items-center gap-2 type-meta text-fg-muted"><slot name="actions"></slot></div>` : nothing}</div>`
				: nothing}
			<div class=${this.flush ? '' : 'p-4'}><slot></slot></div>
		</section>`
	}
}

define('card', Card)

import { html, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { ArrowRight } from 'lucide'
import { DsElement, define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// Door.vue as <conare-door>: a whole card that opens something (console2.css .v2-door), such as Connect an app or Send
// by API. Its border turns ink under the pointer and while what it opens is open (`expanded`). One link or one button.
// Vue's `icon` prop is the `icon` slot here: a 14px Lucide svg with stroke-width 1.5.

/**
 * @summary A whole card that opens something.
 * @slot - Replaces the description.
 * @slot icon - A 14px Lucide icon before the title.
 * @fires click - When pressed.
 */
export class Door extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { heading: {}, description: {}, href: {}, arrow: { type: Boolean }, expanded: { type: Boolean } }

	/** The title (Vue's `title`; `title` is HTML's tooltip attribute). */
	heading = ''
	description?: string
	href?: string
	/** An arrow at the end of the title. */
	arrow = false
	/** What it opens is open (aria-expanded). */
	expanded = false

	render() {
		const classes = 'flex cursor-pointer flex-col gap-1 border border-edge bg-surface p-3 text-left transition-[border-color,background-color] duration-120 ease-standard hover:border-edge-focus active:bg-surface-subtle aria-expanded:border-edge-focus'
		const body = this.description || this.hasSlot()
		const content = html`<span class="flex items-center gap-2 type-ui-strong"><slot name="icon"></slot>${this.heading}${this.arrow ? icon(ArrowRight, 'arrow-right', { size: 12, strokeWidth: 1.5, class: 'ml-auto text-fg-muted', attrs: { 'aria-hidden': 'true' } }) : nothing}</span>${body ? html`<span class="type-meta text-fg-muted"><slot>${this.description}</slot></span>` : nothing}`
		return this.href
			? html`<a data-ds="door" href=${this.href} class=${classes}>${content}</a>`
			: html`<button data-ds="door" type="button" aria-expanded=${ifDefined(this.expanded === undefined ? undefined : String(this.expanded))} class=${classes}>${content}</button>`
	}
}

define('door', Door)
